-- Esquema inicial Supabase. Execute somente após criar projeto Supabase e configurar Auth.
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, owner_name text, business_name text default 'Bela Vista Espaço de Eventos', document text, phone text, address text, late_fee numeric default 100, created_at timestamptz default now());
create table if not exists public.clients (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, phone text, email text, notes text, marketing_consent boolean default false, consent_evidence text, created_at timestamptz default now());
create table if not exists public.events (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, client_id uuid references public.clients(id) on delete set null, client_name text not null, event_date date not null, phone text, price numeric default 0, payment_status text default 'Pendente', handover_time time, return_time time, extras text, notes text, created_at timestamptz default now());
create table if not exists public.expenses (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, description text not null, amount numeric not null, expense_date date default current_date, created_at timestamptz default now());
create table if not exists public.media (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, title text, description text, storage_path text, media_type text, created_at timestamptz default now());
create table if not exists public.audit_log (id bigint generated always as identity primary key, user_id uuid not null references auth.users(id) on delete cascade, action text not null, details jsonb default '{}', created_at timestamptz default now());
create table if not exists public.campaigns (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, message text not null, status text default 'draft', created_at timestamptz default now());
create table if not exists public.campaign_recipients (id uuid primary key default gen_random_uuid(), campaign_id uuid not null references public.campaigns(id) on delete cascade, client_id uuid not null references public.clients(id) on delete cascade, consent_snapshot boolean not null default false, status text default 'pending');
alter table public.profiles enable row level security; alter table public.clients enable row level security; alter table public.events enable row level security; alter table public.expenses enable row level security; alter table public.media enable row level security; alter table public.audit_log enable row level security; alter table public.campaigns enable row level security; alter table public.campaign_recipients enable row level security;
create policy "own profile" on public.profiles for all using (id=auth.uid()) with check (id=auth.uid());
create policy "own clients" on public.clients for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "own events" on public.events for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "own expenses" on public.expenses for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "own media" on public.media for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "own audit" on public.audit_log for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "own campaigns" on public.campaigns for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "own recipients via campaign" on public.campaign_recipients for all using (exists(select 1 from public.campaigns c where c.id=campaign_id and c.user_id=auth.uid())) with check (exists(select 1 from public.campaigns c where c.id=campaign_id and c.user_id=auth.uid()));
